// Find all video elements and their sources
const videos = Array.from(document.querySelectorAll('video'));
const sources = Array.from(document.querySelectorAll('source'));
const links = Array.from(document.querySelectorAll('a[href]')).filter(a => a.href.match(/\.(mp4|mov|webm|avi)/i));

return {
  videoSrcs: videos.map(v => ({ src: v.src, currentSrc: v.currentSrc })),
  sourceSrcs: sources.map(s => ({ src: s.src, type: s.type })),
  videoLinks: links.map(a => a.href),
  pageTitle: document.title
};

